-- =============================================================================
-- Adds the five newest projects at the top and moves existing rows down.
-- Equivalent to pressing Import in the admin. Run once.
-- =============================================================================

update portfolio_items set sort_order = sort_order + 5;

insert into portfolio_items (title, category, description, image_url, link, is_video, sort_order) values
('InteriorX','Websites','Interior design is bought on evidence that the firm has done it before, and most studio sites bury the work behind a philosophy statement. InteriorX leads with the rooms: completed projects by type, residential through commercial, landscape and renovation, with the process broken into the four stages a client is actually agreeing to, from first consultation to final handover. Named designers with their specialisms, a rated client review, years in business and project count carry the credibility, and the quote request sits in reach of every section.','/portfolio/websites/interiorx.webp','https://interiorx-seven.vercel.app',false,0),
('Cardx','Websites','A banking product page needs to make everyday benefits easy to understand. Cardx presents its metal card, virtual cards and budgeting tools through a bold monochrome layout with orange accents and a distinctive mechanical hero illustration. Product benefits, a three-step onboarding overview and a customer story lead visitors towards opening an account, with currency support, spending insights and card controls explained along the way.','/portfolio/websites/cardx.webp','https://cardx-chi.vercel.app/',false,1),
('Lume','Websites','Choosing a lamp is as much about the atmosphere it creates as its specifications. Lume is a lighting storefront built around that decision: warm product photography, a sculptural hero piece and a collection organised into ambient and task lighting with prices visible throughout. A dark palette and restrained gold accents let the lamps carry the page, while shopping, account and contact links stay within reach.','/portfolio/websites/lume.webp','https://lume-topaz-six.vercel.app/',false,2),
('Travel360','Websites','Planning a trip means comparing destinations, flights, hotels and tours without losing track of the experience you want. Travel360 brings those choices into one travel website, pairing destination photography with a prominent search panel for dates, travellers and travel type. Destination cards show starting prices, while trip inspiration, support information and a newsletter give visitors clear ways to keep exploring.','/portfolio/websites/travel360.webp','https://travel360-beige.vercel.app/',false,3),
('Luxury Watches','Websites','A watch buyer wants to see the details, know the price and place an order without a long conversation. Luxury Watches is a product website centred on a matte black unisex watch, with close-up photography, lifestyle images, colour choices and clear naira pricing. The order form collects the buyer''s details, colour and quantity, then prepares a WhatsApp message so the seller can confirm the order and arrange delivery.','/portfolio/websites/luxury-watches.webp','https://luxurywatches-bay.vercel.app/',false,4);

select count(*) as total from portfolio_items;
